informacoes.cabecalho:
                {% for item in registro %}

                
                    {{ item.nome }}
                


                
                    {{ item.email }}
                

                {% if item.permisao == 1 %}
                
                    administrador
                
                {% endif %}
                {% if item.permisao == 0 %}
                
                    usuário
                
                {% endif %}
                {% endfor %}

tabela.registros:
                {% for item in registros %}

                

                    
                        {{ item.id_log }}
                    


                    

                        
                            {{ item.acao }}
                        


                        

                            {% if 'Entrada' in item.acao %}
                                bg-success

                            {% elif 'Novo' in item.acao %}
                                bg-primary

                            {% elif 'Saída' in item.acao %}
                                bg-warning

                            {% elif 'Deletado' in item.acao %}
                                bg-danger

                            {% else %}
                                bg-secondary

                            {% endif %}

                        

                    


                    
                        {{ item.produto_nome }}
                    
                    
                        {{ item.qtd_anterior }}
                        un.
                    
                    
                        {{ item.qtd_nova }}
                        un.
                    
                    
                        {{ item.data_hora }}
                    
                


                {% else %}

                

                    
                        Nenhuma movimentação registrada ainda.
                    

                

                {% endfor %}
